void close_video_buffer_mapping(struct vm_area_struct *vma) {
    struct videobuf_queue *q = vma->vm_private_data;
    struct videobuf_mapping *mapping = q->priv_vma_data;
    int i;

    if (!mapping)
        return;

    if (atomic_dec_and_test(&mapping->count)) {
        spin_lock(&q->lock);
        for (i = 0; i < VIDEO_MAX_FRAME; i++) {
            if (mapping->buffers[i]) {
                q->buf_ops->release(q, mapping->buffers[i]);
                mapping->buffers[i] = NULL;
            }
        }
        spin_unlock(&q->lock);
        kfree(mapping);
        q->priv_vma_data = NULL;
    }
}

void close_video_buffer_mapping(struct vm_area_struct *vma) {
    struct video_buffer_mapping *mapping = vma->vm_private_data;

    if (!mapping)
        return;

    if (atomic_dec_and_test(&mapping->ref_count)) {
        struct video_buffer *buf, *tmp;
        spin_lock(&mapping->queue_lock);
        list_for_each_entry_safe(buf, tmp, &mapping->buffer_list, list) {
            if (buf->ops && buf->ops->release)
                buf->ops->release(buf);
            list_del(&buf->list);
        }
        spin_unlock(&mapping->queue_lock);
        kfree(mapping);
    }
}

